"""Actual Unity world poses vs preserved Blender oracle; fixed bind gauge only."""
import os
for k in ['OPENBLAS_NUM_THREADS','OMP_NUM_THREADS','MKL_NUM_THREADS']:os.environ[k]='6'
from pathlib import Path
import sys,json,hashlib,csv
import numpy as np
R=Path(__file__).resolve().parents[4];O=R/'art/drafts/sailor-native67-dense-v1'/sys.argv[1];meta=json.load(open(O/'result.json'));assert meta['status']=='CAPTURED_ACTUAL_UNITY_POSES_PENDING_OFFLINE_ORACLE' and meta['samples']==6816
source=O.parent/'native67-interchange-v2';sr=json.load(open(source/'report.json'));assert meta['assetSHA256']==sr['export']['SHA256'];z=np.load(source/'original-source-offkey-oracle.npz');names=list(z['boneNames']);assert (O/'bones.txt').read_text().splitlines()==names
actual=np.fromfile(O/'actual-world-poses-f32.bin',dtype='<f4').reshape(6816,67,4,4).astype(float);bind=np.fromfile(O/'bindposes-source-order-f32.bin',dtype='<f4').reshape(67,4,4).astype(float);mesh=np.fromfile(O/'meshWorldBind-f32.bin',dtype='<f4').reshape(4,4).astype(float);assert np.isfinite(actual).all()
geometry=json.load(open(O.parent/'native67-weight-restore-v3/result.json'));assert all(geometry[k] for k in ['allOriginalIds','allTriangles','allCornerUV','positionsVerified']);C=np.array(geometry['coordinateMap']).reshape(4,4);B=mesh@np.linalg.inv(bind);K=np.linalg.inv(z['restWorld'])@np.linalg.inv(C)@B;Q=np.linalg.inv(mesh)@C@z['meshWorld'];invR=np.linalg.inv(z['restWorld']);corners=z['corners'];active=z['active'];maxsum=float(z['maxWeightSum']);rows=[]
def polar(a):u,_,v=np.linalg.svd(a[...,:3,:3]);return u@v
for begin in range(0,len(actual),128):
 end=min(len(actual),begin+128);a=actual[begin:end];s=z['worldPose'][begin:end];expectedSkin=C@s@invR@z['meshWorld'];targetSkin=a@bind@Q;delta=np.einsum('tbij,bkj->tbki',targetSkin-expectedSkin,corners)[...,:3];surface=np.linalg.norm(delta[:,active],axis=-1).max(axis=(1,2))*maxsum
 # Include previously proved full original/seam importer rest-position residual.
 worldInput=a@bind@np.linalg.inv(mesh);restAdd=geometry['vertexMaxM']*np.linalg.norm(worldInput[...,:3,:3],axis=(-2,-1)).max(axis=1)*maxsum;surface+=restAdd
 expectedPose=C@s@K;p=polar(expectedPose);q=polar(a);rel=np.swapaxes(p,-1,-2)@q;xyz=np.stack((rel[...,2,1]-rel[...,1,2],rel[...,0,2]-rel[...,2,0],rel[...,1,0]-rel[...,0,1]),-1);sine=np.linalg.norm(xyz,axis=-1)*.5;cos=np.clip((np.trace(rel,axis1=-2,axis2=-1)-1)*.5,-1,1);angles=np.degrees(np.arctan2(sine,cos)).max(axis=1);joint=np.linalg.norm(a[...,:3,3]-expectedPose[...,:3,3],axis=-1).max(axis=1)
 rows.extend((int(i),str(z['clipNames'][z['clipIndex'][i]]),float(z['times'][i]),float(surface[i-begin]),float(angles[i-begin]),float(joint[i-begin]),float(restAdd[i-begin])) for i in range(begin,end))
a=np.array([[r[3],r[4],r[5],r[6]] for r in rows]);passed=bool(a[:,0].max()<=.0001 and a[:,1].max()<=.01);worst=int(a[:,0].argmax());report={'status':'ACTUAL_UNITY_NATIVE8_FINITE_ORACLE_PASS' if passed else 'ACTUAL_UNITY_NATIVE8_ORACLE_REJECTED_NO_PROMOTION','samples':len(rows),'surfaceBoundMaxM':float(a[:,0].max()),'fixedBindGaugeAngleMaxDeg':float(a[:,1].max()),'jointPositionMaxM':float(a[:,2].max()),'fullSeamRestResidualBoundMaxM':float(a[:,3].max()),'worstSurfaceSample':rows[worst],'surfaceLimitM':.0001,'angleLimitDeg':.01,'actualFBXSHA256':meta['assetSHA256'],'perClip':{name:{'samples':sum(r[1]==name for r in rows),'surfaceBoundMaxM':max(r[3] for r in rows if r[1]==name),'angleMaxDeg':max(r[4] for r in rows if r[1]==name)} for name in z['clipNames']},'sourceScope':'Original spatial CSR support envelopes contain ALL positive influences on ALL994452 original vertices, plus imported full-seam rest residual. NOT a DQS/shoulder-corrected geometry fidelity claim. Finite shifted120Hz schedule only. No moving fit, no threshold change, no game/phone/raster acceptance.','sourceOracleSHA256':hashlib.sha256((source/'original-source-offkey-oracle.npz').read_bytes()).hexdigest(),'actualWorldPosesSHA256':hashlib.sha256((O/'actual-world-poses-f32.bin').read_bytes()).hexdigest()};(O/'oracle-comparison.json').write_text(json.dumps(report,indent=2));
with open(O/'oracle-comparison.csv','w') as f:
 w=csv.writer(f);w.writerow(['sample','clip','seconds','fullOriginalSupportBoundM','fixedGaugeAngleDeg','jointPositionMaxM','fullRestResidualBoundM']);w.writerows(rows)
print(json.dumps(report,indent=2));sys.exit(0 if passed else 1)
